package dsu

import "testing"

func TestBasicUnion(t *testing.T) {
	d := NewDSU(5)
	d.Union(0, 1)
	d.Union(2, 3)
	if !d.Connected(0, 1) {
		t.Error("0 and 1 should be connected")
	}
	if d.Connected(0, 2) {
		t.Error("0 and 2 should not be connected")
	}
}

func TestComponents(t *testing.T) {
	d := NewDSU(5)
	if d.Components() != 5 {
		t.Errorf("initially want 5 components, got %d", d.Components())
	}
	d.Union(0, 1)
	if d.Components() != 4 {
		t.Errorf("after union(0,1) want 4, got %d", d.Components())
	}
	d.Union(2, 3)
	d.Union(0, 2)
	if d.Components() != 2 {
		t.Errorf("after all unions want 2, got %d", d.Components())
	}
}

func TestTransitive(t *testing.T) {
	d := NewDSU(4)
	d.Union(0, 1)
	d.Union(1, 2)
	d.Union(2, 3)
	if !d.Connected(0, 3) {
		t.Error("0 and 3 should be connected transitively")
	}
}

func TestSelfConnection(t *testing.T) {
	d := NewDSU(3)
	if !d.Connected(0, 0) {
		t.Error("node should be connected to itself")
	}
}

func TestZeroNodes(t *testing.T) {
	d := NewDSU(0)
	if d.Components() != 0 {
		t.Errorf("0 nodes want 0 components, got %d", d.Components())
	}
}

